/** Mismo formato que `ICD11` en lib/icd11.ts: Record<code, Icd11Entry>. */
export const ICD11: Record<string, Icd11Entry> = Object.fromEntries(
  ICD11_CATALOG.map(({ code, title, titleEn, id }) => [code, { code, title, titleEn, id }]),
);

/** Pieza FDI → código de extensión CIE-11 (XA…), para poscoordinar: `${stem}&${ICD11_TOOTH_BY_FDI[fdi]}`. */
export const ICD11_TOOTH_BY_FDI: Record<string, string> = Object.fromEntries(
  ICD11_CATALOG.filter((e) => e.fdi).map((e) => [e.fdi as string, e.code]),
);
